 const chooseMetaAccount=async()=>{if(!selectedMetaAccount)return;setBusy('meta-account');await action(async()=>{await send('/meta/account',{office_id:officeId,account_id:selectedMetaAccount},'PUT');await load();},'تم اختيار الحساب الإعلاني ومزامنة الحملات والإعلانات');setBusy('');};
 const syncMeta=async()=>{setBusy('meta-sync');await action(async()=>{await send('/meta/sync',{office_id:officeId});await load();},'تمت مزامنة Meta Ads');setBusy('');};
 const disconnectMeta=async()=>{if(!confirm('فصل حساب Meta عن المكتب؟ الحملات والنتائج اللي اتزامنت هتفضل محفوظة، لكن المزامنة الجديدة هتتوقف.'))return;setBusy('meta-disconnect');await action(async()=>{await send('/meta/connection',{office_id:officeId},'DELETE');await load();},'تم فصل حساب Meta');setBusy('');};
 return <><Heading title="تتبّع حملات المكتب" subtitle="اربط حساب Meta Ads مرة واحدة، وبعدها السيستم يسحب الحملات والإعلانات والمصروف تلقائيًا ويطابقها مع Click-to-WhatsApp."><button className="primary" onClick={()=>setEditCampaign({name:'',meta_campaign_id:'',active:true,office_id:officeId})}><Plus size={17}/> حملة يدوية</button></Heading><Notice>{error}</Notice>
 <section className="card meta-connect-card"><div className="section-heading"><div><span className="eyebrow">META ADS CONNECTION</span><h2>ربط الحساب الإعلاني</h2><p>الربط بصلاحية قراءة فقط للحملات والإعلانات والتكلفة؛ السيستم لا ينشئ أو يوقف حملات Meta.</p></div><span className={'meta-state '+(meta.connected?'connected':'disconnected')}>{meta.connected?'متصل':'غير متصل'}</span></div>
 {!meta.configured?<Notice type="info">شغّل ملف <b>supabase/014_meta_ads_connection.sql</b> في Supabase SQL Editor ثم أعد تشغيل Railway.</Notice>:!meta.env_configured?<><Notice type="info">إعداد Railway ناقص: <b>{(meta.missing_env||[]).join(' · ')}</b>. القيم السرية لا تُكتب داخل لوحة الـCRM.</Notice>{meta.redirect_uri&&<div className="meta-redirect"><small>Valid OAuth Redirect URI داخل Meta App</small><code dir="ltr">{meta.redirect_uri}</code></div>}</>:!meta.connected?<div className="meta-connect-empty"><div><strong>اربط حساب Facebook / Meta Business</strong><small>بعد تسجيل الدخول والموافقة على ads_read وbusiness_management هنقرأ الحسابات الإعلانية المتاحة.</small></div>{manager?<button className="primary" disabled={busy} onClick={connectMeta}><Link2 size={17}/> {busy==='meta-connect'?'جارٍ فتح Meta…':'ربط حساب Meta'}</button>:<small>مدير المكتب أو مسؤول النظام فقط يقدر يعمل الربط.</small>}</div>:<><div className="meta-account-summary"><div><small>الحساب المتصل</small><strong>{meta.connection?.meta_user_name||'Meta Business'}</strong><span>{meta.connection?.token_expires_at?'انتهاء التوكن: '+date(meta.connection.token_expires_at):'توكن بدون تاريخ انتهاء معلن'}</span></div><div><small>آخر مزامنة</small><strong>{meta.connection?.last_sync_at?date(meta.connection.last_sync_at):'لم تتم بعد'}</strong>{meta.connection?.last_sync_error&&<span className="meta-warning">{meta.connection.last_sync_error}</span>}</div></div><div className="meta-account-tools"><label>الحساب الإعلاني<select value={selectedMetaAccount} onChange={e=>setSelectedMetaAccount(e.target.value)}><option value="">اختر الحساب الإعلاني</option>{(meta.accounts||[]).map(a=><option key={a.account_id} value={a.account_id}>{a.name||'Ad Account'} · {a.account_id}{a.currency?' · '+a.currency:''}</option>)}</select></label>{manager&&<><button className="primary" disabled={busy||!selectedMetaAccount} onClick={chooseMetaAccount}>{busy==='meta-account'?'جارٍ المزامنة…':'اختيار الحساب ومزامنة'}</button><button disabled={busy||!meta.connection?.selected_ad_account_id} onClick={syncMeta}><RefreshCw size={15}/> {busy==='meta-sync'?'جارٍ المزامنة…':'مزامنة الآن'}</button><button disabled={busy} onClick={connectMeta}><Link2 size={15}/> إعادة ربط / تحديث الصلاحيات</button><button className="danger" disabled={busy} onClick={disconnectMeta}>فصل Meta</button></>}</div>{meta.connection?.selected_ad_account_name&&<Notice type="info">الحساب المختار: <b>{meta.connection.selected_ad_account_name}</b>{meta.connection.currency?' · العملة '+meta.connection.currency:''}{meta.connection.timezone_name?' · '+meta.connection.timezone_name:''}</Notice>}</>}
 </section>
 <Notice type="info">الـAd ID وFirst Attribution يأتوا تلقائيًا من Click-to-WhatsApp. عند تفعيل Meta Sync، أسماء الحملات والإعلانات وSpend يتم تحديثهم من الحساب الإعلاني، بينما الـZone يظل تحت تحكمك داخل الـCRM.</Notice>
 <div className="campaign-grid">{data.campaigns.map(x=><section className="card" key={x.id}><div className="section-heading"><div><span className="eyebrow">{x.meta_synced_at?'META SYNC':x.active?'حملة نشطة':'متوقفة'}</span><h2>{x.name}</h2>{x.meta_campaign_id&&<small dir="ltr">Campaign ID: {x.meta_campaign_id}</small>}{x.meta_effective_status&&<small>Meta Status: {x.meta_effective_status}</small>}</div><div className="button-row"><button onClick={()=>setEditCampaign({...x,office_id:officeId})}>تعديل</button><button className="danger" onClick={async()=>{if(!confirm('حذف الحملة من الـCRM؟ لن يتم حذفها من Meta Ads.'))return;await action(async()=>{await api('/campaigns/'+x.id+'?office_id='+encodeURIComponent(officeId),{method:'DELETE'});await load();},'تم حذف الحملة من الـCRM');}}>حذف</button></div></div><small>{data.ads.filter(a=>a.campaign_id===x.id).length} إعلان · مصروف {money(data.ads.filter(a=>a.campaign_id===x.id).reduce((n,a)=>n+Number(a.spend||0),0))}</small></section>)}</div>{!data.campaigns.length&&!error&&<section className="card"><Empty><h3>لسه مفيش حملات</h3><p>{meta.connected?'اضغط «مزامنة الآن» لسحب الحملات من Meta.':'اربط حساب Meta أو أضف حملة يدوية.'}</p></Empty></section>}
 <section className="card"><div className="section-heading"><div><h2>أداء الإعلانات</h2><span className="muted">{data.ads.length} Ad ID</span></div></div>{data.ads.length?<div className="table-wrap"><table><thead><tr><th>الإعلان</th><th>الحملة</th><th>Zone</th><th>Spend</th><th>Applicants</th><th>Motorcycle</th><th>Geo</th><th>Qualified</th><th>Hired</th><th>Cost/Hire</th><th/></tr></thead><tbody>{data.ads.map(ad=><tr key={ad.ad_id}><td><strong>{ad.name||ad.headline||'إعلان بدون اسم'}</strong><small dir="ltr">Ad ID: {ad.ad_id}</small>{ad.meta_effective_status&&<small>Meta: {ad.meta_effective_status}</small>}</td><td>{campaignName(ad.campaign_id)}</td><td><span className="zone-chip">{ad.zone||'UNKNOWN'}</span></td><td>{money(ad.spend)}<small>{ad.spend_source==='meta'?'Meta Sync':'Manual'}</small></td><td>{ad.stats?.applicants??ad.stats?.total??0}</td><td>{ad.stats?.motorcycle_qualified||0}</td><td>{ad.stats?.geo_qualified||0}</td><td>{ad.stats?.qualified||0}</td><td>{ad.stats?.hired||0}</td><td>{ad.stats?.costs?.per_hired==null?'—':money(ad.stats.costs.per_hired)}</td><td><button onClick={()=>setEditAd({...ad,zone:ad.zone||'UNKNOWN',spend:String(ad.spend||0)})}>تعديل</button></td></tr>)}</tbody></table></div>:<Empty><h3>لسه مفيش إعلانات</h3><p>بعد Meta Sync أو أول Click-to-WhatsApp هتظهر الإعلانات هنا.</p></Empty>}</section>
 {editCampaign&&<Modal title={editCampaign.id?'تعديل الحملة':'إضافة حملة'} onClose={()=>setEditCampaign(null)}><form onSubmit={async e=>{e.preventDefault();setBusy('campaign');if(await action(async()=>{await send('/campaigns',{...editCampaign,office_id:officeId});await load();},'تم حفظ الحملة'))setEditCampaign(null);setBusy('');}}><label>اسم الحملة<input required maxLength={150} value={editCampaign.name} onChange={e=>setEditCampaign({...editCampaign,name:e.target.value})}/></label><label>Meta Campaign ID (اختياري)<input dir="ltr" maxLength={100} value={editCampaign.meta_campaign_id||''} onChange={e=>setEditCampaign({...editCampaign,meta_campaign_id:e.target.value})}/></label><label className="check"><input type="checkbox" checked={editCampaign.active!==false} onChange={e=>setEditCampaign({...editCampaign,active:e.target.checked})}/>الحملة نشطة</label><button className="primary full" disabled={busy}>{busy?'جارٍ الحفظ…':'حفظ الحملة'}</button></form></Modal>}
 {editAd&&<Modal title="بيانات الإعلان" onClose={()=>setEditAd(null)}><form onSubmit={async e=>{e.preventDefault();setBusy('ad');if(await action(async()=>{await send('/ads/'+encodeURIComponent(editAd.ad_id),{name:editAd.name||'',campaign_id:editAd.campaign_id||null,zone:editAd.zone||'UNKNOWN',spend:Number(editAd.spend||0),office_id:officeId},'PUT');await load();},'تم حفظ الإعلان'))setEditAd(null);setBusy('');}}><label>Ad ID<input dir="ltr" disabled value={editAd.ad_id}/></label><label>اسم الإعلان داخل النظام<input maxLength={200} value={editAd.name||''} onChange={e=>setEditAd({...editAd,name:e.target.value})}/></label><div className="form-grid"><label>الحملة<select value={editAd.campaign_id||''} onChange={e=>setEditAd({...editAd,campaign_id:e.target.value||null})}><option value="">بدون حملة</option>{data.campaigns.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label><label>Zone<select value={editAd.zone||'UNKNOWN'} onChange={e=>setEditAd({...editAd,zone:e.target.value})}>{RECRUITMENT_ZONES.map(z=><option key={z} value={z}>{ZONE_LABELS[z]}</option>)}</select></label></div><label>المصروف المسجل بالجنيه<input dir="ltr" type="number" min="0" step="0.01" value={editAd.spend} onChange={e=>setEditAd({...editAd,spend:e.target.value})}/></label>{editAd.spend_source==='meta'&&<Notice type="info">لو حفظت Spend يدويًا هنا هيتحوّل إلى Manual لحد المزامنة الجاية من Meta.</Notice>}<button className="primary full" disabled={busy}>{busy?'جارٍ الحفظ…':'حفظ الإعلان'}</button></form></Modal>}</>;
